  final result = <String>[];
  for (var r = 0; r < recipes.length; r++) {
    final s = recipes[r];
    var expanded = '';
    var balance = 0;
    var i = 0;
    while (i < s.length) {
      final ch = s[i];
      i++;
      final start = i;
      while (i < s.length) {
        final c = s.codeUnitAt(i);
        if (c < 48 || c > 57) break;
        i++;
      }
      int count;
      if (start == i) {
        count = 1;
      } else {
        count = int.parse(s.substring(start, i));
      }
      for (var k = 0; k < count; k++) {
        expanded = expanded + ch;
        if (ch == 'C') {
          balance = balance + 1;
        } else if (ch == 'D') {
          balance = balance - 1;
        }
      }
    }
    if (balance > 0) {
      result.add(expanded);
    }
  }
  return result;
}

