double fn0(List<double> entries, int window) {
  if (window <= 0) return 0.0;
  if (entries.length < window) return 0.0;

  double sum = 0.0;
  for (int i = 0; i < window; i++) {
    sum += entries[i];
  }

  double best = sum / window;
  for (int i = window; i < entries.length; i++) {
    sum += entries[i] - entries[i - window];
    final double avg = sum / window;
    if (avg > best) {
      best = avg;
    }
  }
  return best;
}

